import { useState, useEffect, useContext, useMemo, useRef, useCallback } from 'react';
import { useIntl } from 'react-intl';
import { orderApi } from '@/services/api';
import { AuthContext } from '@/context/AuthContext';
import { useMarket } from '@/context/MarketContext';
import { criticalMessages } from '@/i18n/messages/criticalMessages';
import { Package, Clock, CheckCircle, ChevronDown, ChevronUp, Zap, Server, ShieldCheck, AlertTriangle, Loader2, MessageSquare, RefreshCw, ShieldAlert, Wallet, XCircle, Download, RotateCcw, Search, Printer } from 'lucide-react';
import { useNavigate, useLocation, useSearchParams } from 'react-router-dom';
import { cn } from '@/lib/utils';
import { useActiveWindowRefresh } from '@/hooks/useActiveWindowRefresh';
import { useSocketDemand } from '@/context/SocketContext';
import { useStableIcuMessages } from '@/i18n/useStableIcuMessages';
import { ACCOUNT_TELEMETRY_EVENTS, trackAccountEvent } from '@/services/accountTelemetry';

const ORDER_FLOW_STAGES = ['placed', 'packed', 'shipped', 'out_for_delivery', 'delivered'];
const SHIPMENT_STATUS_RANK = { pending: 1, packed: 2, shipped: 3, out_for_delivery: 4, delivered: 5 };
const STAGE_LABEL_FALLBACKS = {
    placed: 'Order Confirmed',
    packed: 'Packed',
    shipped: 'Shipped',
    out_for_delivery: 'Out for Delivery',
    delivered: 'Delivered',
    cancelled: 'Cancelled',
};

const getShipmentStage = (orderMeta = {}) => {
    if (orderMeta.orderStatus === 'cancelled' || orderMeta.cancelledAt) return 'cancelled';
    if (orderMeta.isDelivered || orderMeta.orderStatus === 'delivered') return 'delivered';
    const shipments = Array.isArray(orderMeta.shipments) ? orderMeta.shipments : [];
    // 'processing' stays on the confirmed stage until a real packed/shipped
    // checkpoint exists — the legacy admin status alone never claimed packing.
    let rank = orderMeta.orderStatus === 'shipped' ? 3 : 1;
    for (const shipment of shipments) {
        rank = Math.max(rank, SHIPMENT_STATUS_RANK[String(shipment?.status || '')] || 0);
    }
    return ORDER_FLOW_STAGES[Math.min(Math.max(rank, 1), 5) - 1];
};

const getOrderStatusLabel = (orderMeta, t, intl) => {
    const stage = getShipmentStage(orderMeta);
    if (stage === 'placed') {
        return intl.formatMessage(criticalMessages.orderConfirmed);
    }
    return t(`orders.status.${stage}`, {}, STAGE_LABEL_FALLBACKS[stage]);
};

const getCommandStatusLabel = (status, t) => {
    const normalized = String(status || '').toLowerCase();
    switch (normalized) {
        case 'processed':
            return t('orders.command.status.processed', {}, 'processed');
        case 'rejected':
            return t('orders.command.status.rejected', {}, 'rejected');
        case 'shipped':
            return t('orders.command.status.shipped', {}, 'shipped');
        case 'pending':
            return t('orders.command.status.pending', {}, 'pending');
        default:
            return normalized || t('orders.command.status.pending', {}, 'pending');
    }
};

const normalizePaymentState = (order) => {
    const explicit = String(order?.paymentState || '').trim().toLowerCase();
    if (explicit) return explicit;
    if (order?.isPaid) return 'paid';
    return 'pending';
};

const formatPaymentState = (state, intl) => {
    const normalized = String(state || '').trim().toLowerCase();
    if (!normalized) return intl.formatMessage(criticalMessages.paymentPending);
    if (['failed', 'expired', 'cancelled'].includes(normalized)) {
        return intl.formatMessage(criticalMessages.paymentFailed);
    }
    if (['authorized', 'captured', 'paid', 'refunded', 'partially_refunded'].includes(normalized)) {
        return intl.formatMessage(criticalMessages.paymentSuccess);
    }
    if (['pending', 'created', 'challenge_pending'].includes(normalized)) {
        return intl.formatMessage(criticalMessages.paymentPending);
    }
    return normalized.replace(/_/g, ' ');
};

const getPaymentStepToneClass = (state) => {
    switch (state) {
        case 'complete':
            return 'border-neo-cyan/35 bg-neo-cyan/10 text-neo-cyan';
        case 'active':
            return 'border-amber-300/35 bg-amber-400/10 text-amber-200';
        case 'failed':
            return 'border-neo-rose/40 bg-neo-rose/10 text-neo-rose';
        default:
            return 'border-white/10 bg-zinc-950/45 text-slate-300';
    }
};

const getPaymentStepIcon = (state) => {
    if (state === 'complete') return CheckCircle;
    if (state === 'failed') return AlertTriangle;
    return Clock;
};

// Progress tracker: placed → packed → shipped → out for delivery → delivered.
// Stage is derived from the order status plus any shipment checkpoints the
// lifecycle engine has recorded; legacy orders without shipments still land
// on placed/processing correctly.
const OrderProgressStepper = ({ orderMeta, t, intl }) => {
    const stage = getShipmentStage(orderMeta);
    if (stage === 'cancelled') {
        return (
            <div className="rounded-2xl border border-amber-400/30 bg-amber-500/10 p-4">
                <p className="text-xs font-black uppercase tracking-[0.24em] text-amber-200">
                    {t('orders.status.cancelled', {}, 'Cancelled')}
                </p>
            </div>
        );
    }

    const activeIndex = ORDER_FLOW_STAGES.indexOf(stage);
    const shipments = Array.isArray(orderMeta.shipments) ? orderMeta.shipments : [];
    const latestShipment = shipments.length > 0 ? shipments[shipments.length - 1] : null;
    const latestCheckpoint = latestShipment && Array.isArray(latestShipment.checkpoints)
        ? latestShipment.checkpoints[latestShipment.checkpoints.length - 1]
        : null;

    return (
        <div className="rounded-2xl border border-white/10 bg-white/[0.04] p-5">
            <div className="flex items-center justify-between">
                {ORDER_FLOW_STAGES.map((stageKey, index) => {
                    const done = index < activeIndex;
                    const active = index === activeIndex;
                    return (
                        <div key={stageKey} className="flex flex-1 items-center last:flex-none">
                            <div className="flex flex-col items-center gap-2">
                                <div
                                    className={cn(
                                        'h-3 w-3 rounded-full border transition-all duration-300',
                                        done && 'border-neo-cyan bg-neo-cyan shadow-[0_0_8px_rgba(6,182,212,0.7)]',
                                        active && 'h-4 w-4 border-neo-fuchsia bg-neo-fuchsia shadow-[0_0_12px_rgba(217,70,239,0.8)]',
                                        !done && !active && 'border-white/20 bg-zinc-950'
                                    )}
                                    aria-hidden="true"
                                />
                                <span
                                    className={cn(
                                        'whitespace-nowrap text-[9px] font-black uppercase tracking-wider sm:text-[10px]',
                                        active ? 'text-neo-fuchsia' : done ? 'text-neo-cyan' : 'text-slate-500'
                                    )}
                                >
                                    {stageKey === 'placed'
                                        ? intl.formatMessage(criticalMessages.orderConfirmed)
                                        : t(`orders.status.${stageKey}`, {}, STAGE_LABEL_FALLBACKS[stageKey])}
                                </span>
                            </div>
                            {index < ORDER_FLOW_STAGES.length - 1 && (
                                <div
                                    className={cn(
                                        'mx-1 h-[2px] flex-1 rounded sm:mx-2',
                                        index < activeIndex ? 'bg-neo-cyan/70' : 'bg-white/10'
                                    )}
                                    aria-hidden="true"
                                />
                            )}
                        </div>
                    );
                })}
            </div>
            {latestCheckpoint && (
                <p className="mt-3 text-center text-[11px] font-medium text-slate-400">
                    {latestCheckpoint.message
                        || t('orders.progress.latest', {}, 'Latest update received')}
                    {latestShipment?.courier
                        ? ` · ${latestShipment.courier}`
                        : ''}
                    {latestShipment?.trackingId
                        ? ` · ${latestShipment.trackingId}`
                        : ''}
                </p>
            )}
        </div>
    );
};

const EMPTY_ORDER_FILTERS = Object.freeze({
    search: '',
    status: '',
    createdAfter: '',
    createdBefore: '',
});

const ORDER_STATUS_FILTER_VALUES = ['placed', 'processing', 'shipped', 'delivered', 'cancelled'];

const readStatusFromParams = (searchParams) => {
    const status = String(searchParams.get('status') || '').trim().toLowerCase();
    return ORDER_STATUS_FILTER_VALUES.includes(status) ? status : '';
};

const Orders = () => {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [loadingMore, setLoadingMore] = useState(false);
    const [loadError, setLoadError] = useState('');
    const [pagination, setPagination] = useState({ hasMore: false, nextCursor: null });
    const [draftFilters, setDraftFilters] = useState({ ...EMPTY_ORDER_FILTERS });
    const [appliedFilters, setAppliedFilters] = useState(() => ({
        ...EMPTY_ORDER_FILTERS,
        status: readStatusFromParams(new URLSearchParams(window.location.search)),
    }));
    const [livePatches, setLivePatches] = useState({});
    const [placedBanner, setPlacedBanner] = useState(null);
    const { currentUser } = useContext(AuthContext);
    const { t: legacyT, formatPrice } = useMarket();
    const t = useStableIcuMessages(legacyT);
    const intl = useIntl();
    const navigate = useNavigate();
    const location = useLocation();
    const [searchParams, setSearchParams] = useSearchParams();
    const focusOrderId = String(searchParams.get('focus') || '').trim();
    const shouldExpandFocus = searchParams.get('expand') === '1' || searchParams.get('support') === '1';
    const socketContext = useSocketDemand('orders-live', Boolean(currentUser?.uid));
    const socket = socketContext?.socket || null;

    // Checkout hands off success via location.state; consume it once and
    // clear it so a refresh doesn't re-show the banner.
    useEffect(() => {
        if (location.state?.orderPlaced) {
            const orderId = String(location.state?.orderId || '');
            setPlacedBanner({ orderId });
            if (orderId && !focusOrderId) {
                setSearchParams((prev) => {
                    const next = new URLSearchParams(prev);
                    next.set('focus', orderId);
                    next.set('expand', '1');
                    return next;
                }, { replace: true });
            }
            navigate('.', { replace: true, state: null });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Live order updates: the server broadcasts order.updated on every
    // lifecycle event; patch the matching card and let it silently refresh.
    useEffect(() => {
        if (!socket) return undefined;
        const handleOrderUpdated = (payload) => {
            const orderId = String(payload?.orderId || '');
            if (!orderId) return;
            setLivePatches((prev) => ({
                ...prev,
                [orderId]: {
                    ...(prev[orderId] || {}),
                    ...payload,
                    seq: (prev[orderId]?.seq || 0) + 1,
                },
            }));
        };
        socket.on('order.updated', handleOrderUpdated);
        return () => socket.off('order.updated', handleOrderUpdated);
    }, [socket]);

    const filtersActive = useMemo(
        () => Object.values(appliedFilters).some((value) => Boolean(String(value || '').trim())),
        [appliedFilters]
    );

    const refreshOrders = useCallback(async ({ silent = false, append = false, cursor = null } = {}) => {
        if (!currentUser?.uid) {
            setOrders([]);
            setLoading(false);
            return [];
        }

        if (append) {
            setLoadingMore(true);
        } else if (!silent) {
            setLoading(true);
        }
        setLoadError('');

        try {
            const data = await orderApi.getMyOrders({
                cursor: cursor || undefined,
                status: appliedFilters.status || undefined,
                search: appliedFilters.search || undefined,
                createdAfter: appliedFilters.createdAfter
                    ? `${appliedFilters.createdAfter}T00:00:00.000Z`
                    : undefined,
                createdBefore: appliedFilters.createdBefore
                    ? `${appliedFilters.createdBefore}T23:59:59.999Z`
                    : undefined,
            });
            const nextOrders = Array.isArray(data)
                ? [...data]
                : Array.isArray(data?.orders)
                    ? [...data.orders]
                    : [];
            const sortedOrders = nextOrders.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
            setOrders((current) => {
                if (!append) return sortedOrders;
                const merged = new Map(current.map((order) => [String(order._id), order]));
                sortedOrders.forEach((order) => merged.set(String(order._id), order));
                return [...merged.values()].sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
            });
            setPagination({
                hasMore: Boolean(data?.pagination?.hasMore),
                nextCursor: data?.pagination?.nextCursor || null,
            });
            return sortedOrders;
        } catch (error) {
            if (!silent || import.meta.env.DEV) {
                console.error('Failed to fetch orders:', error);
            }
            setLoadError(error.message || t('orders.error.load', {}, 'Unable to load orders'));
            if (!silent && !append) {
                setOrders([]);
            }
            return [];
        } finally {
            if (append) {
                setLoadingMore(false);
            } else if (!silent) {
                setLoading(false);
            }
        }
    }, [appliedFilters, currentUser?.uid, t]);

    const orderSummary = useMemo(() => {
        const activeOrders = orders.filter((order) => {
            const status = String(order.orderStatus || '').toLowerCase();
            return !order.isDelivered && status !== 'cancelled';
        }).length;

        const deliveredOrders = orders.filter((order) => {
            const status = String(order.orderStatus || '').toLowerCase();
            return order.isDelivered || status === 'delivered';
        }).length;

        const protectedPayments = orders.filter((order) => Boolean(order.isPaid)).length;
        const totalSpend = orders.reduce((sum, order) => sum + (Number(order.totalPrice) || 0), 0);

        return [
            {
                label: t('orders.summary.active.label', {}, 'Active Orders Loaded'),
                value: activeOrders,
                detail: t('orders.summary.active.detail', {}, 'Active orders in the currently loaded results.'),
                tone: 'text-neo-cyan',
                icon: Clock,
            },
            {
                label: t('orders.summary.delivered.label', {}, 'Delivered Loaded'),
                value: deliveredOrders,
                detail: t('orders.summary.delivered.detail', {}, 'Delivered orders in the currently loaded results.'),
                tone: 'text-neo-emerald',
                icon: CheckCircle,
            },
            {
                label: t('orders.summary.payments.label', {}, 'Paid Orders Loaded'),
                value: protectedPayments,
                detail: t('orders.summary.payments.detail', {}, 'Loaded orders marked paid by the backend payment state.'),
                tone: 'text-amber-300',
                icon: ShieldCheck,
            },
            {
                label: t('orders.summary.spend.label', {}, 'Loaded Spend'),
                value: formatPrice(totalSpend),
                detail: t('orders.summary.spend.detail', {}, 'Order value from the currently loaded results, not a lifetime total.'),
                tone: 'text-white',
                icon: Wallet,
            },
        ];
    }, [formatPrice, orders, t]);

    useEffect(() => {
        if (!currentUser?.uid) {
            setOrders([]);
            setLoading(false);
            return;
        }

        void refreshOrders();
    }, [currentUser?.uid, refreshOrders]);

    useActiveWindowRefresh(
        () => refreshOrders({ silent: true }),
        { enabled: Boolean(currentUser?.uid) }
    );

    if (!currentUser) {
        return (
            <div className="orders-theme-shell min-h-[80vh] flex items-center justify-center relative overflow-hidden">
                <div className="container-custom py-10">
                    <div className="bg-white/5 border border-white/10 rounded-3xl p-12 text-center max-w-lg mx-auto shadow-glass">
                        <h2 className="text-2xl font-black text-white uppercase tracking-widest mb-6 border-b border-white/10 pb-4">{t('orders.authRequiredTitle', {}, 'Authentication Required')}</h2>
                        <p className="text-slate-400 mb-8">{t('orders.authRequiredBody', {}, 'Sign in to view your order history.')}</p>
                        <button onClick={() => navigate('/login')} className="btn-primary w-full shadow-[0_0_15px_rgba(6,182,212,0.3)]">
                            {intl.formatMessage(criticalMessages.signInAction)}
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    if (loading) {
        return (
            <div className="orders-theme-shell min-h-screen relative overflow-hidden">
                <div className="absolute inset-0 bg-zinc-950" />
                <div className="container-custom py-10 relative">
                    <div className="mb-8 h-10 w-64 animate-pulse rounded-2xl bg-white/5" />
                    <div className="mb-8 h-40 animate-pulse rounded-[1.75rem] bg-white/5" />
                    <div className="space-y-4" aria-busy="true" aria-label={t('orders.loading', {}, 'Loading Orders...')}>
                        {[0, 1, 2].map((key) => (
                            <div key={key} className="rounded-2xl border border-white/10 bg-white/[0.03] p-6">
                                <div className="flex items-center justify-between gap-6">
                                    <div className="flex items-center gap-5">
                                        <div className="h-14 w-14 animate-pulse rounded-xl bg-white/10" />
                                        <div className="space-y-2">
                                            <div className="h-3 w-24 animate-pulse rounded bg-white/10" />
                                            <div className="h-5 w-32 animate-pulse rounded bg-white/10" />
                                        </div>
                                    </div>
                                    <div className="h-6 w-32 animate-pulse rounded-full bg-white/10" />
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    if (orders.length === 0 && !filtersActive && !loadError) {
        return (
            <div className="orders-theme-shell min-h-[80vh] flex items-center justify-center relative overflow-hidden">
                <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[min(80vw,600px)] h-[min(80vw,600px)] bg-neo-fuchsia/5 rounded-full blur-[150px] pointer-events-none -z-10" />
                <div className="container-custom py-10">
                    <div className="bg-white/5 border border-white/10 rounded-3xl p-12 text-center max-w-lg mx-auto shadow-glass relative group overflow-hidden">
                        <div className="absolute inset-0 bg-gradient-to-br from-transparent to-neo-fuchsia/5 opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />

                        <div className="w-24 h-24 rounded-full bg-zinc-950/50 border border-white/10 flex items-center justify-center mx-auto mb-6 shadow-[0_0_30px_rgba(0,0,0,0.5)]">
                            <Package className="w-10 h-10 text-slate-500 group-hover:text-neo-fuchsia transition-colors duration-300" />
                        </div>

                        <h2 className="text-3xl font-black text-white tracking-tight mb-4">{t('orders.emptyTitle', {}, 'No Orders Yet')}</h2>
                        <p className="text-slate-400 mb-8 font-medium">{t('orders.emptyBody', {}, "You haven't placed any orders yet.")}</p>
                        <button onClick={() => navigate('/')} className="btn-primary w-full shadow-[0_0_20px_rgba(217,70,239,0.3)] flex items-center justify-center gap-2">
                            <Zap className="w-4 h-4 fill-white" /> {t('orders.startShopping', {}, 'Start Shopping')}
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="orders-theme-shell min-h-screen pb-20 pt-8 relative">
            <div className="absolute top-0 right-0 w-[min(70vw,500px)] h-[min(70vw,500px)] bg-neo-cyan/5 rounded-full blur-[150px] pointer-events-none -z-10" />

            <div className="container-custom max-w-4xl mx-auto px-4 lg:px-8">
                <div className="flex items-center gap-4 mb-10 pb-6 border-b border-white/10">
                    <Server className="w-8 h-8 text-neo-cyan drop-shadow-[0_0_10px_rgba(6,182,212,0.8)]" />
                    <div>
                        <h1 className="text-3xl font-black text-white tracking-tighter uppercase">{t('orders.title', {}, 'Order History')}</h1>
                        <p className="mt-2 text-sm text-slate-400">{t('orders.subtitle', {}, 'Track delivery, payment, refund, replacement, and support actions from one persistent surface.')}</p>
                    </div>
                </div>

                {placedBanner && (
                    <div
                        role="status"
                        aria-live="polite"
                        className="mb-8 overflow-hidden rounded-[1.75rem] border border-neo-cyan/40 bg-gradient-to-br from-neo-cyan/15 via-neo-cyan/5 to-transparent p-6 shadow-[0_0_30px_rgba(6,182,212,0.15)]"
                    >
                        <div className="flex flex-wrap items-center justify-between gap-4">
                            <div className="flex items-center gap-4">
                                <div className="rounded-2xl border border-neo-cyan/40 bg-neo-cyan/15 p-3">
                                    <CheckCircle className="h-6 w-6 text-neo-cyan" />
                                </div>
                                <div>
                                    <p className="text-lg font-black tracking-tight text-white">
                                        {t('orders.placed.title', {}, 'Order placed successfully!')}
                                    </p>
                                    <p className="text-sm font-medium text-slate-300">
                                        {t('orders.placed.subtitle', {}, 'Your order is confirmed. Track every step right here — we update this page live.')}
                                    </p>
                                </div>
                            </div>
                            <button
                                type="button"
                                className="rounded-xl border border-white/15 px-4 py-2 text-xs font-black uppercase tracking-widest text-slate-200 hover:bg-white/10"
                                onClick={() => setPlacedBanner(null)}
                            >
                                {t('orders.placed.dismiss', {}, 'Dismiss')}
                            </button>
                        </div>
                    </div>
                )}

                <form
                    className="mb-8 rounded-[1.75rem] border border-white/10 bg-white/[0.04] p-5 shadow-glass"
                    onSubmit={(event) => {
                        event.preventDefault();
                        const nextFilters = {
                            ...draftFilters,
                            search: draftFilters.search.trim(),
                        };
                        setAppliedFilters(nextFilters);
                        setSearchParams((prev) => {
                            const next = new URLSearchParams(prev);
                            if (nextFilters.status) {
                                next.set('status', nextFilters.status);
                            } else {
                                next.delete('status');
                            }
                            return next;
                        }, { replace: true });
                        trackAccountEvent(ACCOUNT_TELEMETRY_EVENTS.ORDER_SEARCHED, {
                            hasQuery: Boolean(nextFilters.search),
                            status: nextFilters.status,
                            hasDateRange: Boolean(nextFilters.createdAfter || nextFilters.createdBefore),
                        });
                    }}
                >
                    <div className="flex items-center gap-2 text-[11px] font-black uppercase tracking-[0.24em] text-neo-cyan">
                        <Search className="h-4 w-4" />
                        {t('orders.filters.title', {}, 'Filter Order History')}
                    </div>
                    <div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                        <label className="text-sm font-bold text-slate-300">
                            <span className="mb-2 block">{t('orders.filters.search', {}, 'Order or payment ID')}</span>
                            <input
                                type="search"
                                value={draftFilters.search}
                                onChange={(event) => setDraftFilters((current) => ({ ...current, search: event.target.value }))}
                                className="w-full rounded-xl border border-white/10 bg-zinc-950/70 px-3 py-2.5 text-white"
                                maxLength={100}
                            />
                        </label>
                        <label className="text-sm font-bold text-slate-300">
                            <span className="mb-2 block">{t('orders.filters.status', {}, 'Status')}</span>
                            <select
                                value={draftFilters.status}
                                onChange={(event) => setDraftFilters((current) => ({ ...current, status: event.target.value }))}
                                className="w-full rounded-xl border border-white/10 bg-zinc-950/70 px-3 py-2.5 text-white"
                            >
                                <option value="">{t('orders.filters.statusAll', {}, 'All statuses')}</option>
                                <option value="placed">{t('orders.filters.statusPlaced', {}, 'Placed')}</option>
                                <option value="processing">{t('orders.filters.statusProcessing', {}, 'Processing')}</option>
                                <option value="shipped">{t('orders.filters.statusShipped', {}, 'Shipped')}</option>
                                <option value="delivered">{t('orders.filters.statusDelivered', {}, 'Delivered')}</option>
                                <option value="cancelled">{t('orders.filters.statusCancelled', {}, 'Cancelled')}</option>
                            </select>
                        </label>
                        <label className="text-sm font-bold text-slate-300">
                            <span className="mb-2 block">{t('orders.filters.from', {}, 'From date')}</span>
                            <input
                                type="date"
                                value={draftFilters.createdAfter}
                                onChange={(event) => setDraftFilters((current) => ({ ...current, createdAfter: event.target.value }))}
                                className="w-full rounded-xl border border-white/10 bg-zinc-950/70 px-3 py-2.5 text-white"
                            />
                        </label>
                        <label className="text-sm font-bold text-slate-300">
                            <span className="mb-2 block">{t('orders.filters.to', {}, 'To date')}</span>
                            <input
                                type="date"
                                value={draftFilters.createdBefore}
                                onChange={(event) => setDraftFilters((current) => ({ ...current, createdBefore: event.target.value }))}
                                className="w-full rounded-xl border border-white/10 bg-zinc-950/70 px-3 py-2.5 text-white"
                            />
                        </label>
                    </div>
                    <div className="mt-4 flex flex-wrap gap-3">
                        <button type="submit" className="btn-primary px-5 py-2.5">
                            {t('orders.filters.apply', {}, 'Apply Filters')}
                        </button>
                        <button
                            type="button"
                            className="rounded-xl border border-white/15 px-5 py-2.5 text-sm font-bold text-slate-200"
                            onClick={() => {
                                setDraftFilters({ ...EMPTY_ORDER_FILTERS });
                                setAppliedFilters({ ...EMPTY_ORDER_FILTERS });
                                setSearchParams((prev) => {
                                    const next = new URLSearchParams(prev);
                                    next.delete('status');
                                    return next;
                                }, { replace: true });
                            }}
                        >
                            {t('orders.filters.clear', {}, 'Clear Filters')}
                        </button>
                    </div>
                </form>

                {loadError && (
                    <div role="alert" className="mb-8 rounded-2xl border border-neo-rose/35 bg-neo-rose/10 p-4 text-neo-rose">
                        <p>{loadError}</p>
                        <button type="button" className="mt-3 font-black underline" onClick={() => refreshOrders()}>
                            {t('orders.error.retry', {}, 'Retry')}
                        </button>
                    </div>
                )}

                <section className="mb-8 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                    {orderSummary.map((item) => (
                        <article
                            key={item.label}
                            className="rounded-[1.5rem] border border-white/10 bg-white/[0.045] p-5 shadow-glass"
                        >
                            <div className="flex items-center justify-between gap-3">
                                <div className="text-[11px] font-black uppercase tracking-[0.22em] text-slate-400">{item.label}</div>
                                <item.icon className={cn('h-4 w-4', item.tone)} />
                            </div>
                            <div className={cn('mt-4 text-3xl font-black', item.tone)}>{item.value}</div>
                            <p className="mt-2 text-sm leading-6 text-slate-400">{item.detail}</p>
                        </article>
                    ))}
                </section>

                <section className="mb-8 rounded-[1.75rem] border border-white/10 bg-white/[0.04] p-5 shadow-glass">
                    <div className="flex items-center gap-2 text-[11px] font-black uppercase tracking-[0.24em] text-neo-cyan">
                        <ShieldCheck className="h-4 w-4" />
                        {t('orders.trustLayerTitle', {}, 'Post-Purchase Trust Layer')}
                    </div>
                    <div className="mt-4 grid gap-3 md:grid-cols-3">
                        <div className="rounded-2xl border border-white/8 bg-zinc-950/35 px-4 py-4 text-sm text-slate-300">
                            <span className="mr-2 text-neo-cyan">•</span>
                            {t('orders.trustNote1', {}, 'Order status, payment state, and command-center actions are read from backend order records.')}
                        </div>
                        <div className="rounded-2xl border border-white/8 bg-zinc-950/35 px-4 py-4 text-sm text-slate-300">
                            <span className="mr-2 text-neo-emerald">•</span>
                            {t('orders.trustNote2', {}, 'Refund, replacement, warranty, and support requests remain attached to the originating order.')}
                        </div>
                        <div className="rounded-2xl border border-white/8 bg-zinc-950/35 px-4 py-4 text-sm text-slate-300">
                            <span className="mr-2 text-amber-300">•</span>
                            {t('orders.trustNote3', {}, 'Each order card exposes trust timeline events before you trigger a disruptive action.')}
                        </div>
                    </div>
                </section>

                <div className="space-y-6">
                    {orders.length === 0 && filtersActive && (
                        <div className="rounded-2xl border border-white/10 bg-white/[0.04] p-8 text-center text-slate-300">
                            <Package className="mx-auto mb-3 h-8 w-8 text-slate-500" />
                            {t('orders.filters.empty', {}, 'No orders match these filters.')}
                        </div>
                    )}
                    {orders.map((order) => (
                        <OrderCard
                            key={order._id}
                            order={order}
                            autoExpand={shouldExpandFocus && String(order._id) === focusOrderId}
                            livePatch={livePatches[String(order._id)]}
                        />
                    ))}
                    {pagination.hasMore && pagination.nextCursor && (
                        <button
                            type="button"
                            className="w-full rounded-2xl border border-neo-cyan/30 bg-neo-cyan/10 px-5 py-4 font-black text-neo-cyan"
                            disabled={loadingMore}
                            onClick={() => refreshOrders({ append: true, cursor: pagination.nextCursor })}
                        >
                            {loadingMore
                                ? t('orders.pagination.loading', {}, 'Loading more orders...')
                                : t('orders.pagination.more', {}, 'Load More Orders')}
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

export const OrderCard = ({ order, autoExpand = false, livePatch = null }) => {
    const [expanded, setExpanded] = useState(false);
    const { t: legacyT, formatDateTime, formatPrice } = useMarket();
    const t = useStableIcuMessages(legacyT);
    const intl = useIntl();
    const navigate = useNavigate();
    const [orderMeta, setOrderMeta] = useState({
        orderStatus: order.orderStatus || (order.isDelivered ? 'delivered' : 'placed'),
        isDelivered: Boolean(order.isDelivered),
        isPaid: Boolean(order.isPaid),
        shipments: Array.isArray(order.shipments) ? order.shipments : [],
    });
    const [timeline, setTimeline] = useState([]);
    const [timelineLoading, setTimelineLoading] = useState(false);
    const [timelineError, setTimelineError] = useState('');
    const [commandCenter, setCommandCenter] = useState(null);
    const [commandLoading, setCommandLoading] = useState(false);
    const [commandError, setCommandError] = useState('');
    const [commandSubmitting, setCommandSubmitting] = useState('');
    const [orderAction, setOrderAction] = useState('');
    const [orderActionStatus, setOrderActionStatus] = useState('');
    const [orderActionError, setOrderActionError] = useState('');
    const [commandInput, setCommandInput] = useState({
        cancelReason: '',
        refundReason: '',
        refundAmount: '',
        replaceReason: '',
        supportMessage: '',
        warrantyIssue: '',
    });
    const cardRef = useRef(null);

    // Legacy or partial order records must never crash the card render.
    const safeOrderId = String(order?._id || '');
    const safeOrderItems = Array.isArray(order?.orderItems) ? order.orderItems : [];
    const safeShippingAddress = order?.shippingAddress || {};

    // A live `order.updated` broadcast patches the card in place and silently
    // re-syncs the timeline + command center (the 30s poll stays as fallback).
    useEffect(() => {
        if (!livePatch) return;
        setOrderMeta((prev) => ({
            ...prev,
            orderStatus: livePatch.orderStatus || prev.orderStatus,
            isDelivered: livePatch.orderStatus === 'delivered' ? true : prev.isDelivered,
            shipments: Array.isArray(livePatch.shipments) && livePatch.shipments.length > 0
                ? livePatch.shipments
                : prev.shipments,
        }));
        refreshTimeline({ silent: true });
        refreshCommandCenter({ silent: true });
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [livePatch?.seq]);

    const refreshTimeline = useCallback(async ({ silent = false } = {}) => {
        if (!silent) {
            setTimelineLoading(true);
        }
        setTimelineError('');

        try {
            const response = await orderApi.getOrderTimeline(order._id);
            setTimeline(Array.isArray(response?.timeline) ? response.timeline : []);
        } catch (error) {
            setTimelineError(error.message || t('orders.timeline.error.load', {}, 'Unable to load trust timeline'));
        } finally {
            if (!silent) {
                setTimelineLoading(false);
            }
        }
    }, [order._id, t]);

    const refreshCommandCenter = useCallback(async ({ silent = false } = {}) => {
        if (!silent) {
            setCommandLoading(true);
        }
        setCommandError('');
        try {
            const response = await orderApi.getCommandCenter(order._id);
            setCommandCenter(response?.commandCenter || null);
        } catch (error) {
            setCommandError(error.message || t('orders.command.error.refresh', {}, 'Unable to refresh command center'));
        } finally {
            if (!silent) {
                setCommandLoading(false);
            }
        }
    }, [order._id, t]);

    // Format Date
    const date = String(formatDateTime(order.createdAt, undefined, {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
    }) || t('orders.date.unknown', {}, 'Unknown')).toUpperCase();

    useEffect(() => {
        if (!autoExpand) return;
        setExpanded(true);
        window.requestAnimationFrame(() => {
            cardRef.current?.scrollIntoView({
                behavior: 'smooth',
                block: 'start',
            });
        });
    }, [autoExpand]);

    useEffect(() => {
        setOrderMeta({
            orderStatus: order.orderStatus || (order.isDelivered ? 'delivered' : 'placed'),
            isDelivered: Boolean(order.isDelivered),
            isPaid: Boolean(order.isPaid),
            shipments: Array.isArray(order.shipments) ? order.shipments : [],
        });
    }, [order._id, order.isDelivered, order.isPaid, order.orderStatus, order.shipments]);

    useEffect(() => {
        if (!expanded || timelineLoading || timeline.length > 0 || timelineError) {
            return undefined;
        }
        void refreshTimeline();
        return undefined;
    }, [expanded, refreshTimeline, timeline.length, timelineError, timelineLoading]);

    useEffect(() => {
        if (!expanded || commandLoading || commandCenter || commandError) {
            return undefined;
        }
        void refreshCommandCenter();
        return undefined;
    }, [commandCenter, commandError, commandLoading, expanded, refreshCommandCenter]);

    const formatTimelineDate = (value) => {
        const dateValue = new Date(value);
        if (!Number.isFinite(dateValue.getTime())) return t('orders.date.unknown', {}, 'Unknown');
        return formatDateTime(dateValue, undefined, {
            day: '2-digit',
            month: 'short',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true,
        });
    };

    const paymentTimelineItems = useMemo(() => {
        const paymentState = normalizePaymentState({ ...order, isPaid: orderMeta.isPaid });
        const failedState = ['failed', 'expired', 'cancelled'].includes(paymentState);
        const capturedState = ['captured', 'paid', 'refunded', 'partially_refunded'].includes(paymentState);
        const authorizedState = capturedState || paymentState === 'authorized';
        const paymentEvents = timeline.filter((event) => ['payment', 'risk'].includes(String(event?.stage || '').toLowerCase()));
        const challengeEvent = paymentEvents.find((event) => String(event?.type || '').includes('challenge'));
        const refundEntries = [
            ...(Array.isArray(order?.refundSummary?.refunds) ? order.refundSummary.refunds : []),
            ...(Array.isArray(commandCenter?.refunds) ? commandCenter.refunds : []),
        ];
        const latestRefund = refundEntries
            .filter(Boolean)
            .sort((left, right) => new Date(right.processedAt || right.createdAt || 0) - new Date(left.processedAt || left.createdAt || 0))[0];

        const items = [
            {
                key: 'method',
                title: t('orders.payment.timeline.method', {}, 'Method Selected'),
                detail: [
                    order.paymentMethod || t('orders.payment.methodUnknown', {}, 'Unknown method'),
                    order.paymentProvider || '',
                ].filter(Boolean).join(' via '),
                at: order.createdAt,
                state: 'complete',
            },
            {
                key: 'request',
                title: t('orders.payment.timeline.request', {}, 'Payment Request'),
                detail: order.paymentIntentId
                    ? `${t('orders.payment.intent', {}, 'Intent')} ${String(order.paymentIntentId).slice(-10)}`
                    : t('orders.payment.codRequest', {}, 'No digital intent required for COD'),
                at: order.createdAt,
                state: order.paymentMethod === 'COD' || order.paymentIntentId ? 'complete' : 'pending',
            },
        ];

        if (challengeEvent) {
            items.push({
                key: 'challenge',
                title: challengeEvent.title || t('orders.payment.timeline.challenge', {}, 'Security Challenge'),
                detail: challengeEvent.detail || t('orders.payment.timeline.challengeBody', {}, 'Additional payment verification was requested.'),
                at: challengeEvent.at,
                state: String(challengeEvent.severity || '') === 'critical' ? 'failed' : 'complete',
            });
        }

        items.push({
            key: 'authorization',
            title: t('orders.payment.timeline.authorization', {}, 'Authorization'),
            detail: failedState
                ? formatPaymentState(paymentState, intl)
                : authorizedState
                    ? t('orders.payment.timeline.authorizedBody', {}, 'Provider authorization accepted')
                    : t('orders.payment.timeline.awaitingAuthorization', {}, 'Awaiting provider authorization'),
            at: order.paymentAuthorizedAt || order.paidAt || order.updatedAt || order.createdAt,
            state: failedState ? 'failed' : authorizedState ? 'complete' : 'active',
        });

        items.push({
            key: 'capture',
            title: t('orders.payment.timeline.capture', {}, 'Capture and Settlement'),
            detail: failedState
                ? t('orders.payment.timeline.captureStopped', {}, 'Capture stopped because payment did not authorize')
                : capturedState
                    ? formatPaymentState(paymentState, intl)
                    : authorizedState
                        ? t('orders.payment.timeline.capturePending', {}, 'Capture is pending in the backend queue')
                        : t('orders.payment.timeline.captureWaiting', {}, 'Waiting for authorization first'),
            at: order.paymentCapturedAt || order.paidAt || order.updatedAt || order.createdAt,
            state: failedState ? 'failed' : capturedState ? 'complete' : authorizedState ? 'active' : 'pending',
        });

        if (latestRefund || ['refunded', 'partially_refunded'].includes(paymentState)) {
            const refundStatus = latestRefund?.status || paymentState;
            items.push({
                key: 'refund',
                title: t('orders.payment.timeline.refund', {}, 'Refund'),
                detail: formatPaymentState(refundStatus, intl),
                at: latestRefund?.processedAt || latestRefund?.createdAt || order.updatedAt || order.createdAt,
                state: ['processed', 'refunded', 'partially_refunded'].includes(String(refundStatus || '').toLowerCase())
                    ? 'complete'
                    : 'active',
            });
        }

        return items;
    }, [
        commandCenter?.refunds,
        intl,
        order,
        orderMeta.isPaid,
        t,
        timeline,
    ]);

    const timelineToneClass = (severity) => {
        switch (severity) {
            case 'critical':
                return 'border-neo-rose/40 bg-neo-rose/10 text-neo-rose';
            case 'warning':
                return 'border-amber-400/40 bg-amber-400/10 text-amber-300';
            default:
                return 'border-neo-cyan/35 bg-neo-cyan/10 text-neo-cyan';
        }
    };

    const timelineDotClass = (severity) => {
        switch (severity) {
            case 'critical':
                return 'bg-neo-rose border-neo-rose/80';
            case 'warning':
                return 'bg-amber-300 border-amber-300/80';
            default:
                return 'bg-neo-cyan border-neo-cyan/80';
        }
    };

    useActiveWindowRefresh(
        () => Promise.all([
            refreshTimeline({ silent: true }),
            refreshCommandCenter({ silent: true }),
        ]),
        { enabled: expanded }
    );

    const submitCommand = async (type) => {
        setCommandSubmitting(type);
        setCommandError('');
        try {
            if (type === 'cancel') {
                const response = await orderApi.cancelOrder(order._id, {
                    reason: commandInput.cancelReason || t('orders.command.cancel.defaultReason', {}, 'Cancelled by customer'),
                });
                setCommandInput((prev) => ({ ...prev, cancelReason: '' }));
                if (response?.order) {
                    setOrderMeta({
                        orderStatus: response.order.orderStatus || 'cancelled',
                        isDelivered: Boolean(response.order.isDelivered),
                        isPaid: Boolean(response.order.isPaid),
                    });
                } else {
                    setOrderMeta((prev) => ({ ...prev, orderStatus: 'cancelled' }));
                }
                setTimeline([]);
            } else if (type === 'refund') {
                await orderApi.requestRefund(order._id, {
                    reason: commandInput.refundReason || t('orders.command.refund.defaultReason', {}, 'Customer refund request'),
                    amount: commandInput.refundAmount ? Number(commandInput.refundAmount) : undefined,
                });
                setCommandInput((prev) => ({ ...prev, refundReason: '', refundAmount: '' }));
                trackAccountEvent(ACCOUNT_TELEMETRY_EVENTS.RETURN_STARTED, {
                    resolution: 'refund',
                });
            } else if (type === 'replace') {
                const firstItem = order.orderItems?.[0];
                await orderApi.requestReplacement(order._id, {
                    reason: commandInput.replaceReason || t('orders.command.replace.defaultReason', {}, 'Product issue reported'),
                    itemProductId: firstItem?.product || firstItem?.id,
                    itemTitle: firstItem?.title,
                });
                setCommandInput((prev) => ({ ...prev, replaceReason: '' }));
                trackAccountEvent(ACCOUNT_TELEMETRY_EVENTS.RETURN_STARTED, {
                    resolution: 'replacement',
                });
            } else if (type === 'support') {
                await orderApi.sendSupportMessage(order._id, {
                    message: commandInput.supportMessage || t('orders.command.support.defaultMessage', {}, 'Need help with this order.'),
                });
                setCommandInput((prev) => ({ ...prev, supportMessage: '' }));
            } else if (type === 'warranty') {
                const firstItem = order.orderItems?.[0];
                await orderApi.createWarrantyClaim(order._id, {
                    issue: commandInput.warrantyIssue || t('orders.command.warranty.defaultIssue', {}, 'Warranty support needed'),
                    itemProductId: firstItem?.product || firstItem?.id,
                    itemTitle: firstItem?.title,
                });
                setCommandInput((prev) => ({ ...prev, warrantyIssue: '' }));
            }
            await refreshCommandCenter();
        } catch (error) {
            setCommandError(error.message || t('orders.command.error.action', {}, 'Command center action failed'));
        } finally {
            setCommandSubmitting('');
        }
    };

    const downloadReceipt = async () => {
        setOrderAction('receipt');
        setOrderActionError('');
        setOrderActionStatus('');
        try {
            const receipt = await orderApi.getReceipt(order._id);
            const blob = new Blob([JSON.stringify(receipt, null, 2)], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            const anchor = document.createElement('a');
            anchor.href = url;
            anchor.download = `aura-receipt-${order._id}.json`;
            document.body.appendChild(anchor);
            anchor.click();
            anchor.remove();
            URL.revokeObjectURL(url);
            setOrderActionStatus(t('orders.actions.receiptReady', {}, 'Receipt downloaded.'));
        } catch (error) {
            setOrderActionError(error.message || t('orders.actions.receiptError', {}, 'Unable to download receipt.'));
        } finally {
            setOrderAction('');
        }
    };

    const buyAgain = async () => {
        setOrderAction('buyAgain');
        setOrderActionError('');
        setOrderActionStatus('');
        try {
            await orderApi.buyAgain(order._id);
            trackAccountEvent(ACCOUNT_TELEMETRY_EVENTS.BUY_AGAIN_SELECTED, {
                itemCount: order.orderItems?.length,
            });
            setOrderActionStatus(t('orders.actions.buyAgainReady', {}, 'Available items were added to your cart.'));
            navigate('/cart');
        } catch (error) {
            setOrderActionError(error.message || t('orders.actions.buyAgainError', {}, 'Unable to add this order to your cart.'));
        } finally {
            setOrderAction('');
        }
    };

    return (
        <div ref={cardRef} className={cn("bg-white/5 rounded-2xl shadow-glass border transition-all duration-300 overflow-hidden relative group", expanded ? "border-neo-cyan/50 shadow-[0_0_25px_rgba(6,182,212,0.15)] bg-zinc-950/80" : "border-white/10 hover:border-white/30")}>
            {expanded && <div className="absolute top-0 left-0 w-1 h-full bg-gradient-to-b from-neo-cyan to-neo-fuchsia z-10" />}

            {/* Header */}
            <div
                className="p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6 cursor-pointer relative z-10"
                role="button"
                tabIndex={0}
                aria-expanded={expanded}
                aria-label={t('orders.card.toggle', {}, 'Toggle order details')}
                onClick={() => setExpanded(!expanded)}
                onKeyDown={(event) => {
                    if (event.key === 'Enter' || event.key === ' ') {
                        event.preventDefault();
                        setExpanded(!expanded);
                    }
                }}
            >

                <div className="flex gap-5 items-center">
                    <div className="bg-zinc-950/80 border border-white/10 p-4 rounded-xl shadow-inner group-hover:border-neo-cyan/40 transition-colors">
                        <Package className="w-6 h-6 text-neo-cyan" />
                    </div>
                    <div>
                        <p className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-1">{t('orders.orderId', {}, 'Order ID')}: <span className="font-mono text-neo-fuchsia tracking-normal ml-1">#{safeOrderId.slice(-8).toUpperCase()}</span></p>
                        <h3 className="font-black text-white text-xl tracking-tight">{formatPrice(order.totalPrice)}</h3>
                    </div>
                </div>

                <div className="flex items-center gap-6 w-full sm:w-auto justify-between sm:justify-end border-t border-white/10 sm:border-0 pt-4 sm:pt-0 mt-2 sm:mt-0">
                    <div className="flex flex-col items-start sm:items-end gap-1.5">
                        <p className="text-xs font-bold text-slate-400 tracking-wider">{t('orders.dateLabel', {}, 'Date')}: {date}</p>
                        <span className={cn("text-[10px] px-3 py-1 rounded border font-black uppercase tracking-widest flex items-center gap-1.5",
                            orderMeta.orderStatus === 'cancelled'
                                ? 'bg-amber-500/15 border-amber-400/30 text-amber-200 shadow-[0_0_10px_rgba(251,191,36,0.2)]'
                                : orderMeta.isDelivered
                                ? 'bg-neo-cyan/10 border-neo-cyan/30 text-neo-cyan shadow-[0_0_10px_rgba(6,182,212,0.2)]'
                                : 'bg-neo-rose/10 border-neo-rose/30 text-neo-rose shadow-[0_0_10px_rgba(244,63,94,0.2)]'
                        )}>
                            {orderMeta.orderStatus === 'cancelled'
                                ? <XCircle className="w-3 h-3" />
                                : orderMeta.isDelivered
                                    ? <CheckCircle className="w-3 h-3" />
                                    : <Clock className="w-3 h-3" />}
                            {getOrderStatusLabel(orderMeta, t, intl)}
                        </span>
                    </div>
                    <div className="w-8 h-8 rounded-full bg-zinc-950/50 border border-white/10 flex items-center justify-center text-slate-400 group-hover:text-white transition-colors">
                        {expanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                    </div>
                </div>
            </div>

            {/* Details (Collapsible) */}
            {expanded && (
                <div className="p-6 border-t border-white/5 bg-zinc-950/50 relative z-10 animate-fade-in">
                    <div className="space-y-4">
                        <OrderProgressStepper orderMeta={orderMeta} t={t} intl={intl} />
                        <h4 className="font-bold text-xs text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">{t('orders.itemsTitle', {}, 'Items in Order')}</h4>
                        {safeOrderItems.map((item, index) => (
                            <div key={index} className="flex gap-6 items-center bg-white/5 p-4 rounded-xl border border-white/10 hover:bg-white/10 transition-colors">
                                <div className="w-16 h-16 bg-zinc-950/80 rounded-lg p-2 border border-white/5 flex items-center justify-center">
                                    <img src={item.image} alt={item.title} className="w-full h-full object-contain mix-blend-screen" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className="font-bold text-white line-clamp-1 text-sm">{item.title}</p>
                                    <p className="text-xs font-bold text-neo-cyan mt-1">{t('orders.qty', {}, 'Qty')}: {item.quantity}</p>
                                </div>
                                <p className="font-black text-white whitespace-nowrap">{formatPrice(item.price)}</p>
                            </div>
                        ))}
                    </div>

                    <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-6 text-sm">
                        <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                            <h4 className="font-black text-white text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-neo-fuchsia shadow-[0_0_5px_rgba(217,70,239,0.8)]" />
                                {t('orders.addressTitle', {}, 'Target Coordinates')}
                            </h4>
                            <div className="space-y-1 text-slate-300 font-medium leading-relaxed">
                                <p className="text-white">{safeShippingAddress.address || '—'}</p>
                                <p>{safeShippingAddress.city}, {safeShippingAddress.postalCode}</p>
                                <p>{safeShippingAddress.country}</p>
                            </div>
                        </div>
                        <div className="bg-white/5 p-6 rounded-2xl border border-white/10">
                            <h4 className="font-black text-white text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-neo-cyan shadow-[0_0_5px_rgba(6,182,212,0.8)]" />
                                {t('orders.paymentTitle', {}, 'Payment Details')}
                            </h4>
                            <div className="flex justify-between items-center py-2 border-b border-white/5">
                                <span className="text-slate-400 font-bold uppercase tracking-wider text-[10px]">{t('orders.paymentMethod', {}, 'Method')}:</span>
                                <span className="font-medium text-white">{order.paymentMethod}</span>
                            </div>
                            <div className="flex justify-between items-center mt-3">
                                <span className="text-slate-400 font-bold uppercase tracking-wider text-[10px]">{t('orders.paymentVerification', {}, 'Verification')}:</span>
                                <span className={cn("font-black tracking-wider uppercase text-[10px] px-2 py-1 rounded border",
                                    orderMeta.isPaid
                                        ? 'bg-neo-cyan/10 border-neo-cyan/30 text-neo-cyan shadow-[0_0_8px_rgba(6,182,212,0.3)]'
                                        : 'bg-neo-rose/10 border-neo-rose/30 text-neo-rose shadow-[0_0_8px_rgba(244,63,94,0.3)]'
                                )}>
                                    {orderMeta.isPaid ? t('orders.payment.paid', {}, 'Paid') : t('orders.payment.pending', {}, 'Pending')}
                                </span>
                            </div>
                        </div>
                    </div>

                    <div className="mt-8 rounded-2xl border border-white/10 bg-white/5 p-5">
                        <div className="flex flex-wrap gap-3">
                            <button
                                type="button"
                                className="flex items-center gap-2 rounded-xl border border-white/15 px-4 py-2.5 text-sm font-black text-white"
                                disabled={Boolean(orderAction)}
                                onClick={downloadReceipt}
                            >
                                {orderAction === 'receipt'
                                    ? <Loader2 className="h-4 w-4 animate-spin" />
                                    : <Download className="h-4 w-4" />}
                                {t('orders.actions.receipt', {}, 'Download Receipt')}
                            </button>
                            <button
                                type="button"
                                className="flex items-center gap-2 rounded-xl border border-white/15 px-4 py-2.5 text-sm font-black text-white"
                                onClick={() => navigate(`/orders/${safeOrderId}/invoice`)}
                            >
                                <Printer className="h-4 w-4" />
                                {t('orders.actions.invoice', {}, 'Invoice')}
                            </button>
                            <button
                                type="button"
                                className="flex items-center gap-2 rounded-xl border border-neo-cyan/30 bg-neo-cyan/10 px-4 py-2.5 text-sm font-black text-neo-cyan"
                                disabled={Boolean(orderAction)}
                                onClick={buyAgain}
                            >
                                {orderAction === 'buyAgain'
                                    ? <Loader2 className="h-4 w-4 animate-spin" />
                                    : <RotateCcw className="h-4 w-4" />}
                                {t('orders.actions.buyAgain', {}, 'Buy Again')}
                            </button>
                        </div>
                        {orderActionStatus && (
                            <p role="status" aria-live="polite" className="mt-3 text-sm text-neo-emerald">
                                {orderActionStatus}
                            </p>
                        )}
                        {orderActionError && (
                            <p role="alert" className="mt-3 text-sm text-neo-rose">
                                {orderActionError}
                            </p>
                        )}
                    </div>

                    <div className="mt-8 bg-white/5 p-6 rounded-2xl border border-white/10">
                        <div className="mb-4 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                            <h4 className="font-black text-white text-xs uppercase tracking-widest flex items-center gap-2">
                                <Wallet className="w-4 h-4 text-amber-300" />
                                {t('orders.payment.timeline.title', {}, 'Payment Timeline')}
                            </h4>
                            <span className={cn(
                                'w-fit rounded-full border px-2.5 py-1 text-[10px] font-black uppercase tracking-[0.18em]',
                                getPaymentStepToneClass(
                                    ['failed', 'expired'].includes(normalizePaymentState(order)) ? 'failed' : orderMeta.isPaid ? 'complete' : 'active'
                                )
                            )}>
                                {formatPaymentState(normalizePaymentState(order), intl)}
                            </span>
                        </div>

                        <div className="grid gap-3 md:grid-cols-2">
                            {paymentTimelineItems.map((item) => {
                                const StepIcon = getPaymentStepIcon(item.state);
                                return (
                                    <div
                                        key={item.key}
                                        className={cn('rounded-xl border p-4', getPaymentStepToneClass(item.state))}
                                    >
                                        <div className="flex items-start gap-3">
                                            <div className="mt-0.5 rounded-lg border border-current/20 bg-current/10 p-2">
                                                <StepIcon className="h-4 w-4" />
                                            </div>
                                            <div className="min-w-0">
                                                <p className="text-[11px] font-black uppercase tracking-[0.18em]">{item.title}</p>
                                                <p className="mt-1 text-xs leading-5 text-slate-100/90">{item.detail}</p>
                                                <p className="mt-2 text-[10px] font-semibold tracking-wider opacity-70">{formatTimelineDate(item.at)}</p>
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    <div className="mt-8 bg-white/5 p-6 rounded-2xl border border-white/10">
                        <h4 className="font-black text-white text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
                            <ShieldCheck className="w-4 h-4 text-neo-cyan" />
                            {t('orders.timelineTitle', {}, 'Trust Timeline')}
                        </h4>

                        {timelineLoading && (
                            <div className="flex items-center gap-2 text-slate-300 text-sm">
                                <Loader2 className="w-4 h-4 animate-spin text-neo-cyan" />
                                {t('orders.timeline.loading', {}, 'Loading trust events...')}
                            </div>
                        )}

                        {!timelineLoading && timelineError && (
                            <div className="rounded-xl border border-neo-rose/35 bg-neo-rose/10 px-4 py-3 text-sm text-neo-rose flex items-center gap-2">
                                <AlertTriangle className="w-4 h-4" />
                                {timelineError}
                            </div>
                        )}

                        {!timelineLoading && !timelineError && timeline.length === 0 && (
                            <p className="text-sm text-slate-400">{t('orders.timeline.empty', {}, 'No timeline events available yet.')}</p>
                        )}

                        {!timelineLoading && !timelineError && timeline.length > 0 && (
                            <ol className="space-y-3">
                                {timeline.map((event, index) => (
                                    <li key={`${event.type}-${event.at}-${index}`} className="flex gap-3 items-start">
                                        <div className={cn(
                                            'mt-1 w-2.5 h-2.5 rounded-full border',
                                            timelineDotClass(event.severity)
                                        )} />
                                        <div className={cn('flex-1 rounded-xl border px-3 py-2', timelineToneClass(event.severity))}>
                                            <div className="flex items-center justify-between gap-3">
                                                <p className="text-xs font-black uppercase tracking-wider">{event.title}</p>
                                                <span className="text-[10px] font-bold uppercase tracking-wider opacity-80">{event.stage}</span>
                                            </div>
                                            {event.detail && (
                                                <p className="mt-1 text-xs text-slate-100/90">{event.detail}</p>
                                            )}
                                            <p className="mt-1 text-[10px] font-semibold tracking-wider opacity-70">{formatTimelineDate(event.at)}</p>
                                        </div>
                                    </li>
                                ))}
                            </ol>
                        )}
                    </div>

                    <div className="mt-8 bg-white/5 p-6 rounded-2xl border border-white/10">
                        <div className="flex items-center justify-between gap-3 mb-4">
                            <h4 className="font-black text-white text-xs uppercase tracking-widest flex items-center gap-2">
                                <Server className="w-4 h-4 text-neo-emerald" />
                                {t('orders.command.title', {}, 'Post-Purchase Command Center')}
                            </h4>
                            <button
                                type="button"
                                onClick={refreshCommandCenter}
                                className="inline-flex items-center gap-1.5 rounded-lg border border-white/15 bg-white/5 px-2.5 py-1 text-[11px] font-bold uppercase tracking-wider text-slate-300 hover:text-white"
                            >
                                <RefreshCw className={cn('w-3.5 h-3.5', commandLoading && 'animate-spin')} />
                                {t('orders.command.refresh', {}, 'Refresh')}
                            </button>
                        </div>

                        {commandLoading && (
                            <div className="flex items-center gap-2 text-slate-300 text-sm">
                                <Loader2 className="w-4 h-4 animate-spin text-neo-emerald" />
                                {t('orders.command.loading', {}, 'Loading command center...')}
                            </div>
                        )}

                        {!commandLoading && commandError && (
                            <div className="rounded-xl border border-neo-rose/35 bg-neo-rose/10 px-4 py-3 text-sm text-neo-rose flex items-center gap-2">
                                <AlertTriangle className="w-4 h-4" />
                                {commandError}
                            </div>
                        )}

                        {!commandLoading && !commandError && (
                            <div className="space-y-4">
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/50 p-3">
                                        <p className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">{t('orders.command.stats.refunds', {}, 'Refund Requests')}</p>
                                        <p className="text-lg font-black text-white">{commandCenter?.refunds?.length || 0}</p>
                                    </div>
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/50 p-3">
                                        <p className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">{t('orders.command.stats.replacements', {}, 'Replacements')}</p>
                                        <p className="text-lg font-black text-white">{commandCenter?.replacements?.length || 0}</p>
                                    </div>
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/50 p-3">
                                        <p className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">{t('orders.command.stats.support', {}, 'Support Messages')}</p>
                                        <p className="text-lg font-black text-white">{commandCenter?.supportChats?.length || 0}</p>
                                    </div>
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/50 p-3">
                                        <p className="text-[10px] uppercase tracking-wider text-slate-400 font-bold">{t('orders.command.stats.warranty', {}, 'Warranty Claims')}</p>
                                        <p className="text-lg font-black text-white">{commandCenter?.warrantyClaims?.length || 0}</p>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-amber-300 flex items-center gap-1.5 mb-2">
                                            <XCircle className="w-3.5 h-3.5" />
                                            {t('orders.command.cancel.title', {}, 'Cancel Order')}
                                        </p>
                                        <input
                                            type="text"
                                            placeholder={t('orders.command.cancel.placeholder', {}, 'Cancellation reason')}
                                            value={commandInput.cancelReason}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, cancelReason: e.target.value }))}
                                            className="w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-amber-300"
                                        />
                                        <button
                                            type="button"
                                            disabled={commandSubmitting === 'cancel' || orderMeta.orderStatus === 'cancelled' || orderMeta.isDelivered}
                                            onClick={() => submitCommand('cancel')}
                                            className="mt-2 w-full rounded-lg border border-amber-300/35 bg-amber-500/10 px-3 py-2 text-xs font-black uppercase tracking-wider text-amber-200 disabled:opacity-60"
                                        >
                                            {orderMeta.orderStatus === 'cancelled'
                                                ? t('orders.command.cancel.already', {}, 'Already Cancelled')
                                                : commandSubmitting === 'cancel'
                                                    ? t('orders.command.cancel.submitting', {}, 'Cancelling...')
                                                    : t('orders.command.cancel.submit', {}, 'Cancel Order')}
                                        </button>
                                    </div>

                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-neo-cyan flex items-center gap-1.5 mb-2">
                                            <Wallet className="w-3.5 h-3.5" />
                                            {t('orders.command.refund.title', {}, 'Refund')}
                                        </p>
                                        <input
                                            type="text"
                                            placeholder={t('orders.command.refund.placeholder', {}, 'Reason')}
                                            value={commandInput.refundReason}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, refundReason: e.target.value }))}
                                            className="w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-neo-cyan"
                                        />
                                        <input
                                            type="number"
                                            placeholder={t('orders.command.refund.amountPlaceholder', {}, 'Amount (optional)')}
                                            value={commandInput.refundAmount}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, refundAmount: e.target.value }))}
                                            className="mt-2 w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-neo-cyan"
                                        />
                                        <button
                                            type="button"
                                            disabled={commandSubmitting === 'refund' || orderMeta.orderStatus === 'cancelled'}
                                            onClick={() => submitCommand('refund')}
                                            className="mt-2 w-full rounded-lg border border-neo-cyan/35 bg-neo-cyan/15 px-3 py-2 text-xs font-black uppercase tracking-wider text-neo-cyan disabled:opacity-60"
                                        >
                                            {commandSubmitting === 'refund' ? t('orders.command.refund.submitting', {}, 'Submitting...') : t('orders.command.refund.submit', {}, 'Request Refund')}
                                        </button>
                                    </div>

                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-amber-200 flex items-center gap-1.5 mb-2">
                                            <RefreshCw className="w-3.5 h-3.5" />
                                            {t('orders.command.replace.title', {}, 'Replacement')}
                                        </p>
                                        <input
                                            type="text"
                                            placeholder={t('orders.command.replace.placeholder', {}, 'Replacement reason')}
                                            value={commandInput.replaceReason}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, replaceReason: e.target.value }))}
                                            className="w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-amber-300"
                                        />
                                        <button
                                            type="button"
                                            disabled={commandSubmitting === 'replace' || orderMeta.orderStatus === 'cancelled'}
                                            onClick={() => submitCommand('replace')}
                                            className="mt-2 w-full rounded-lg border border-amber-300/35 bg-amber-500/10 px-3 py-2 text-xs font-black uppercase tracking-wider text-amber-200 disabled:opacity-60"
                                        >
                                            {commandSubmitting === 'replace' ? t('orders.command.replace.submitting', {}, 'Submitting...') : t('orders.command.replace.submit', {}, 'Request Replacement')}
                                        </button>
                                    </div>

                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-neo-emerald flex items-center gap-1.5 mb-2">
                                            <MessageSquare className="w-3.5 h-3.5" />
                                            {t('orders.command.support.title', {}, 'Support Chat')}
                                        </p>
                                        <textarea
                                            placeholder={t('orders.command.support.placeholder', {}, 'Ask support team')}
                                            value={commandInput.supportMessage}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, supportMessage: e.target.value }))}
                                            rows={3}
                                            className="w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-neo-emerald resize-none"
                                        />
                                        <button
                                            type="button"
                                            disabled={commandSubmitting === 'support'}
                                            onClick={() => submitCommand('support')}
                                            className="mt-2 w-full rounded-lg border border-neo-emerald/35 bg-neo-emerald/15 px-3 py-2 text-xs font-black uppercase tracking-wider text-neo-emerald disabled:opacity-60"
                                        >
                                            {commandSubmitting === 'support' ? t('orders.command.support.sending', {}, 'Sending...') : t('orders.command.support.submit', {}, 'Send Message')}
                                        </button>
                                    </div>

                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-fuchsia-200 flex items-center gap-1.5 mb-2">
                                            <ShieldAlert className="w-3.5 h-3.5" />
                                            {t('orders.command.warranty.title', {}, 'Warranty Claim')}
                                        </p>
                                        <textarea
                                            placeholder={t('orders.command.warranty.placeholder', {}, 'Describe warranty issue')}
                                            value={commandInput.warrantyIssue}
                                            onChange={(e) => setCommandInput((prev) => ({ ...prev, warrantyIssue: e.target.value }))}
                                            rows={3}
                                            className="w-full rounded-lg border border-white/15 bg-zinc-950/60 px-3 py-2 text-xs text-white outline-none focus:border-fuchsia-300 resize-none"
                                        />
                                        <button
                                            type="button"
                                            disabled={commandSubmitting === 'warranty'}
                                            onClick={() => submitCommand('warranty')}
                                            className="mt-2 w-full rounded-lg border border-fuchsia-300/35 bg-fuchsia-500/10 px-3 py-2 text-xs font-black uppercase tracking-wider text-fuchsia-200 disabled:opacity-60"
                                        >
                                            {commandSubmitting === 'warranty' ? t('orders.command.warranty.submitting', {}, 'Submitting...') : t('orders.command.warranty.submit', {}, 'Open Claim')}
                                        </button>
                                    </div>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-neo-cyan mb-3">{t('orders.command.refund.operations', {}, 'Refund Operations')}</p>
                                        {(commandCenter?.refunds || []).length === 0 ? (
                                            <p className="text-xs text-slate-400">{t('orders.command.refund.empty', {}, 'No refund operations yet.')}</p>
                                        ) : (
                                            <div className="space-y-2 max-h-56 overflow-auto pr-1">
                                                {[...(commandCenter?.refunds || [])].reverse().map((entry) => (
                                                    <div key={entry.requestId} className="rounded-lg border border-white/10 bg-zinc-950/60 p-2.5">
                                                        <div className="flex items-center justify-between gap-2">
                                                            <span className="text-[10px] font-black uppercase tracking-wider text-slate-300">#{entry.requestId?.slice(-8)}</span>
                                                            <span className={cn(
                                                                'text-[10px] px-2 py-0.5 rounded border font-black uppercase tracking-wider',
                                                                entry.status === 'processed'
                                                                    ? 'border-emerald-300/40 text-emerald-200 bg-emerald-500/10'
                                                                    : entry.status === 'rejected'
                                                                        ? 'border-rose-300/40 text-rose-200 bg-rose-500/10'
                                                                    : 'border-amber-300/40 text-amber-200 bg-amber-500/10'
                                                            )}>
                                                                {getCommandStatusLabel(entry.status, t)}
                                                            </span>
                                                        </div>
                                                        <p className="mt-1 text-xs text-white">{entry.message || entry.reason || t('orders.command.refund.requestFallback', {}, 'Refund request')}</p>
                                                        <p className="text-[11px] text-slate-400">{t('orders.amount', {}, 'Amount')}: {formatPrice(entry.amount || 0)}</p>
                                                        {entry.refundId && (
                                                            <p className="text-[10px] text-neo-cyan">{t('orders.refundId', {}, 'Refund ID')}: {entry.refundId}</p>
                                                        )}
                                                        <p className="text-[10px] text-slate-500">
                                                            {formatTimelineDate(entry.processedAt || entry.createdAt)}
                                                        </p>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>

                                    <div className="rounded-xl border border-white/10 bg-zinc-950/40 p-4">
                                        <p className="text-xs font-black uppercase tracking-[0.14em] text-amber-200 mb-3">{t('orders.command.replace.operations', {}, 'Replacement Operations')}</p>
                                        {(commandCenter?.replacements || []).length === 0 ? (
                                            <p className="text-xs text-slate-400">{t('orders.command.replace.empty', {}, 'No replacements yet.')}</p>
                                        ) : (
                                            <div className="space-y-2 max-h-56 overflow-auto pr-1">
                                                {[...(commandCenter?.replacements || [])].reverse().map((entry) => (
                                                    <div key={entry.requestId} className="rounded-lg border border-white/10 bg-zinc-950/60 p-2.5">
                                                        <div className="flex items-center justify-between gap-2">
                                                            <span className="text-[10px] font-black uppercase tracking-wider text-slate-300">#{entry.requestId?.slice(-8)}</span>
                                                            <span className={cn(
                                                                'text-[10px] px-2 py-0.5 rounded border font-black uppercase tracking-wider',
                                                                entry.status === 'shipped'
                                                                    ? 'border-emerald-300/40 text-emerald-200 bg-emerald-500/10'
                                                                    : entry.status === 'rejected'
                                                                        ? 'border-rose-300/40 text-rose-200 bg-rose-500/10'
                                                                    : 'border-amber-300/40 text-amber-200 bg-amber-500/10'
                                                            )}>
                                                                {getCommandStatusLabel(entry.status, t)}
                                                            </span>
                                                        </div>
                                                        <p className="mt-1 text-xs text-white">{entry.itemTitle || t('orders.itemFallback', {}, 'Item')} {entry.message ? `- ${entry.message}` : ''}</p>
                                                        <p className="text-[11px] text-slate-400">{t('orders.qty', {}, 'Qty')}: {entry.quantity || 1}</p>
                                                        {entry.trackingId && (
                                                            <p className="text-[10px] text-neo-emerald">{t('orders.tracking', {}, 'Tracking')}: {entry.trackingId}</p>
                                                        )}
                                                        <p className="text-[10px] text-slate-500">
                                                            {formatTimelineDate(entry.processedAt || entry.createdAt)}
                                                        </p>
                                                    </div>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default Orders;
